import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Muundo wa Usimamizi na Usawa wa Mamlaka","description":"","frontmatter":{},"headers":[],"relativePath":"sw/49-治理框架与权力制衡.md","filePath":"sw/49-治理框架与权力制衡.md","lastUpdated":1789183869000}'),l={name:"sw/49-治理框架与权力制衡.md"};function m(k,a,e,w,s,h){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="muundo-wa-usimamizi-na-usawa-wa-mamlaka" tabindex="-1">Muundo wa Usimamizi na Usawa wa Mamlaka <a class="header-anchor" href="#muundo-wa-usimamizi-na-usawa-wa-mamlaka" aria-label="Permalink to &quot;Muundo wa Usimamizi na Usawa wa Mamlaka&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>49</td></tr><tr><td>Moduli</td><td>Mfumo wa Kisheria na Muundo wa Usimamizi</td></tr><tr><td>Maneno muhimu ya msingi</td><td>Mgawanyiko wa Mamlaka Tatu, Usawa wa Mamlaka, Baraza la Nanga, Kamiti ya Ufuatiliaji, Usimamizi wa Usawa</td></tr></tbody></table><h2 id="_1-muundo-wa-jumla-wa-muundo-wa-usimamizi" tabindex="-1">1. Muundo wa Jumla wa Muundo wa Usimamizi <a class="header-anchor" href="#_1-muundo-wa-jumla-wa-muundo-wa-usimamizi" aria-label="Permalink to &quot;1. Muundo wa Jumla wa Muundo wa Usimamizi&quot;">​</a></h2><p>Muundo wa usimamizi wa ustaarabu wa usawa wa nanga unachukua 《Katiba ya Usawa》 kama msingi wa kimsingi, na unatekelezwa muundo wa usimamizi wa &quot;mgawanyiko wa mamlaka tatu, usawa wa mamlaka nne&quot;. Mamlaka tatu inamaanisha mamlaka ya kisheria, mamlaka ya utawala, na mamlaka ya haki, ambazo zinatekelezwa kwa mtiririko na Baraza la Nanga, Kamiti ya Tekelezaji ya Usawa, na Mahakama ya Usawa; mamlaka ya nne ni mamlaka ya ufuatiliaji, ambayo inatekelezwa na Kamiti ya Ufuatiliaji ya Nanga ya uhuru, na inafanya ufuatiliaji wa kamili juu ya mamlaka tatu. Lengo kuu la muundo huu ni kuzuia ukaribishaji na unyanyafu wa mamlaka, na kuondoa misingi ya usimamizi wa mauaji kutoka kwa kiwango cha kitaaluma.</p><p>Muundo wa usimamizi unafuata kanuni zifuatazo:</p><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maudhui</th></tr></thead><tbody><tr><td>Kanuni ya Mgawanyiko wa Mamlaka</td><td>Mamlaka tatu za kisheria, utawala, na haki zinatekelezwa kwa mtiririko na mashirika tofauti, na hazifai kuchukuliwa pamoja</td></tr><tr><td>Kanuni ya Usawa wa Mamlaka</td><td>Kila shirika la mamlaka linazuia na kufuatilia kwa kushirikiana, na kuzuia upande wowote kuwa na mamlaka kubwa sana</td></tr><tr><td>Kanuni ya Ushiriki wa Kabila zote</td><td>Muundo wa mashirika ya usimamizi lazima uonyeshe uwakilishi wa kabila zote, na kuhakikisha kila kabila linaweza kushiriki katika maswala ya umma</td></tr><tr><td>Kanuni ya Ukusanyaji wa Kidemokrasia</td><td>Maamuzi makubwa yanaamuliwa kwa ukusanyaji baada ya majadiliano kamili ya kidemokrasia, na kuzingatia ufanisi na kidemokrasia</td></tr><tr><td>Kanuni ya Ujitawala wa Msingi</td><td>Maswala ya msingi yanasimamiwa na shirika la ujitawala la msingi, na mashirika ya juu hayafai kuingilia vya kuzidi</td></tr><tr><td>Kanuni ya Usimamizi wa Uwazi</td><td>Mchakato wa usimamizi na taarifa za maamuzi zinachapishwa kulingana na sheria, na zinapokea ufuatiliaji wa umma</td></tr></tbody></table><h2 id="_2-mamlaka-ya-kisheria-baraza-la-nanga" tabindex="-1">2. Mamlaka ya Kisheria: Baraza la Nanga <a class="header-anchor" href="#_2-mamlaka-ya-kisheria-baraza-la-nanga" aria-label="Permalink to &quot;2. Mamlaka ya Kisheria: Baraza la Nanga&quot;">​</a></h2><p>Baraza la Nanga ni shirika la juu la mamlaka la ustaarabu wa usawa wa nanga, na linatekeleza mamlaka ya kisheria na mamlaka ya maamuzi ya maswala muhimu.</p><h3 id="_1-muundo-na-asili" tabindex="-1">(1) Muundo na Asili <a class="header-anchor" href="#_1-muundo-na-asili" aria-label="Permalink to &quot;(1) Muundo na Asili&quot;">​</a></h3><ul><li><strong>Muundo wa Wawakilishi</strong>: Baraza la Nanga linajumuisha wawakilishi wa kabila zote kwa uwiano, na wawakilishi wa kabila la binadamu havizidi 30% ya jumla, na viti vilivyobaki vinagawanywa kulingana na ukubwa wa idadi ya watu na kiwango cha mchango wa kila kabila.</li><li><strong>Muda wa Wawakilishi</strong>: Muda wa wawakilishi wa baraza ni miaka mitano, na wanaweza kuchaguliwa tena, lakini kuchaguliwa tena hakifai kuzidi muda matatu.</li><li><strong>Njia ya Uchaguzi</strong>: Wawakilishi wanachaguliwa kupitia uchaguzi wa kidemokrasia wa ndani wa kila kabila, na mchakato wa uchaguzi ni wazi na wazi, na unapokea ufuatiliaji.</li><li><strong>Shirika la Daima</strong>: Wakati wa mapumziko ya baraza, kamiti ya kudumu inatekeleza baadhi ya mamlaka, na wanachama wa kamiti ya kudumu wanachaguliwa kati ya wawakilishi.</li></ul><h3 id="_2-eneo-la-mamlaka" tabindex="-1">(2) Eneo la Mamlaka <a class="header-anchor" href="#_2-eneo-la-mamlaka" aria-label="Permalink to &quot;(2) Eneo la Mamlaka&quot;">​</a></h3><ol><li><strong>Mamlaka ya Kisheria</strong>: Kuandaa na kurekebisha katiba, sheria za msingi, na sheria nyingine muhimu.</li><li><strong>Mamlaka ya Maamuzi ya Maswala Muhimu</strong>: Kuamua mipango ya maendeleo ya ustaarabu, bajeti ya kila mwaka, vita na amani, maendeleo ya plano, na maswala mengine muhimu.</li><li><strong>Mamlaka ya Uteuzi na Kufukuza</strong>: Kuchagua na kufukuza mwenyekiti wa Kamiti ya Tekelezaji ya Usawa, mwenyekiti wa Mahakama ya Usawa, mkurugenzi wa Kamiti ya Ufuatiliaji ya Nanga, na maafisa wengine makuu.</li><li><strong>Mamlaka ya Ufuatiliaji</strong>: Kufuatilia kazi ya Kamiti ya Tekelezaji ya Usawa na Mahakama ya Usawa, kusikiliza na kuchunguza ripoti za kazi.</li><li><strong>Mamlaka ya Kurekebisha Katiba</strong>: Kurekebisha katiba kinahitaji idhini ya多数 zaidi ya theluthi mbili na referendum ya watu.</li></ol><h3 id="_3-kanuni-za-majadiliano" tabindex="-1">(3) Kanuni za Majadiliano <a class="header-anchor" href="#_3-kanuni-za-majadiliano" aria-label="Permalink to &quot;(3) Kanuni za Majadiliano&quot;">​</a></h3><ul><li>Baraza linafanya mkutano mmoja wa jumla kila mwaka, na linaweza kuitikia mkutano wa dharura inapohitajika.</li><li>Kuchunguza rasimu ya sheria kunatekelezwa mfumo wa &quot;kusoma mara tatu&quot;: kusoma mara ya kwanza kinachunguza hitaji la kisheria, kusoma mara ya pili kinachunguza maudhui ya kifungu, na kusoma mara ya tatu kinapiga kura kwa idhini. | Kupiga kura kunatekeleza mtu mmoja kura moja, na sheria za jumla zinapidhiwa kwa多数 rahisi, na kurekebisha katiba kinapidhiwa kwa多数 zaidi ya theluthi mbili.</li><li>Mchakato wa majadiliano unafanyika kwa uwazi, na kuruhusu umma kuhudhuria kama wasikilizaji na habari za vyombo vya habari.</li></ul><h2 id="_3-mamlaka-ya-utawala-kamiti-ya-tekelezaji-ya-usawa" tabindex="-1">3. Mamlaka ya Utawala: Kamiti ya Tekelezaji ya Usawa <a class="header-anchor" href="#_3-mamlaka-ya-utawala-kamiti-ya-tekelezaji-ya-usawa" aria-label="Permalink to &quot;3. Mamlaka ya Utawala: Kamiti ya Tekelezaji ya Usawa&quot;">​</a></h2><p>Kamiti ya Tekelezaji ya Usawa ni shirika la juu la utawala la ustaarabu wa usawa wa nanga, na linahusika na utekelezaji wa katiba na sheria, na usimamizi wa kila siku.</p><h3 id="_1-muundo-na-asili-1" tabindex="-1">(1) Muundo na Asili <a class="header-anchor" href="#_1-muundo-na-asili-1" aria-label="Permalink to &quot;(1) Muundo na Asili&quot;">​</a></h3><ul><li><strong>Mfumo wa Mwenyekiti</strong>: Kamiti ya Tekelezaji ya Usawa inatekeleza mfumo wa uwajibikaji wa mwenyekiti, na mwenyekiti ni kiongozi wa utawala, anayechaguliwa na Baraza la Nanga, na muda wake ni miaka mitano, na anaweza kuchaguliwa tena mara moja.</li><li><strong>Muundo wa Wanachama</strong>: Kamiti inajumuisha mwenyekiti, makamu wa mwenyekiti, na viongozi wa kila idara, na viongozi wa kila idara wanateuliwa na mwenyekiti na wanaagizwa na baraza.</li><li><strong>Kiasi cha Kabila la Nje</strong>: Uwiano wa kabila la nje kati ya wanachama wa kamiti hakichini ya 40%, na kuhakikisha maamuzi ya utawala yanazingatia maslahi ya kila kabila.</li></ul><h3 id="_2-eneo-la-mamlaka-1" tabindex="-1">(2) Eneo la Mamlaka <a class="header-anchor" href="#_2-eneo-la-mamlaka-1" aria-label="Permalink to &quot;(2) Eneo la Mamlaka&quot;">​</a></h3><ol><li><strong>Mamlaka ya Kisheria ya Utawala</strong>: Kuandaa kanuni za utawala, sheria, na sera kulingana na katiba na sheria.</li><li><strong>Mamlaka ya Usimamizi wa Utawala</strong>: Kuongoza na kusimamia shughuli mbalimbali za utawala kama vile uchumi, elimu, sayansi, utamaduni, afya, michezo, mazingira, n.k.</li><li><strong>Mamlaka ya Usimamizi wa Watu</strong>: Kuteua, kutoa mafunzo, kutathmini, na kutupa zawadi/kuadhibu wafanyakazi wa utawala kulingana na masharti ya sheria.</li><li><strong>Mamlaka ya Ubalozi</strong>: Kuwakilisha ustaarabu wa usawa katika shughuli za ubalozi za kati ya plano, na kusaini mikataba na makubaliano.</li><li><strong>Mamlaka ya Hali ya Dharura</strong>: Katika tukio la dharura linalofuata, inaweza kutangaza hali ya dharura na kuchukua hatua za dharura kulingana na sheria, lakini lazima itoe ripodi kwa idhini ya baraza ndani ya muda uliobainishwa.</li></ol><h3 id="_3-mipangilio-ya-idara-za-utawala" tabindex="-1">(3) Mipangilio ya Idara za Utawala <a class="header-anchor" href="#_3-mipangilio-ya-idara-za-utawala" aria-label="Permalink to &quot;(3) Mipangilio ya Idara za Utawala&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Idara</th><th>Kazi Kuu</th></tr></thead><tbody><tr><td>Idara ya Maendeleo ya Usawa</td><td>Kuandaa mipango ya maendeleo ya ustaarabu, kuratibu maendeleo ya nyanja mbalimbali</td></tr><tr><td>Idara ya Usimamizi wa Rasilimali</td><td>Kusimamia rasilimali za mazoezi na rasilimali za umma, kutekeleza mfumo wa mkataba wa uzalishaji wa pamoja</td></tr><tr><td>Idara ya Elimu na Utamaduni</td><td>Kusimamia kazi za elimu na maswala ya utamaduni</td></tr><tr><td>Idara ya Afya na Tiba</td><td>Kusimamia kazi za afya na tiba na afya ya umma</td></tr><tr><td>Idara ya Mazingira na Mazingira</td><td>Kusimamia ulinzi wa mazingira na ujenzi wa mazingira</td></tr><tr><td>Idara ya Maswala ya Plano</td><td>Kusimamia maendeleo ya plano na maswala ya kati ya plano</td></tr><tr><td>Idara ya Maswala ya Kabila zote</td><td>Kuratibu uhusiano wa kabila zote, kushughulikia maswala ya kabila la nje</td></tr><tr><td>Idara ya Fedha na Uchumi</td><td>Kusimamia bajeti ya fedha na uendeshaji wa uchumi</td></tr><tr><td>Idara ya Usalama</td><td>Kudumisha usalama wa umma na usalama wa ustaarabu</td></tr></tbody></table><h2 id="_4-mamlaka-ya-haki-mahakama-ya-usawa" tabindex="-1">4. Mamlaka ya Haki: Mahakama ya Usawa <a class="header-anchor" href="#_4-mamlaka-ya-haki-mahakama-ya-usawa" aria-label="Permalink to &quot;4. Mamlaka ya Haki: Mahakama ya Usawa&quot;">​</a></h2><p>Mahakama ya Usawa ni shirika la juu la haki la ustaarabu wa usawa wa nanga, na linatekeleza uwezo wa hukumu kwa uhuru. Mfumo wake wa shirikisho, mchakato wa mashtaka, na mfumo wa uchunguzi wa katiba umeelezwa kwa undani katika 《48-Mfumo wa Haki na Mfumo wa Maamuzi》.</p><p>Katika muundo wa usawa wa mamlaka, uzuili wa mamlaka ya haki juu ya mamlaka ya kisheria na mamlaka ya utawala unaonyeshwa katika:</p><ol><li><strong>Mamlaka ya Uchunguzi wa Katiba</strong>: Mahakama ya Usawa ina mamlaka ya kutangaza sheria na kanuni za utawala zinazovunja katiba zisiyo na ufanisi.</li><li><strong>Mamlaka ya Hukumu ya Utawala</strong>: Mahakama ina mamlaka ya kuhukumu mashtaka ya utawala, na kuchunguza halali ya tabia ya utawala.</li><li><strong>Mamlaka ya Hukumu ya Kufukuza</strong>: Mashtaka ya kufukuza maafisa wakuu yaliyowasilishwa na baraza yannahukumiwa na Mahakama ya Usawa.</li></ol><p>Wakati huo huo, mamlaka ya haki pia inazuiliwa na mamlaka ya kisheria na mamlaka ya utawala: wanaohukumu wanaagizwa na baraza, bajeti ya haki inatayarishwa na idara ya utawala (lakini inahitaji idhini ya baraza na haiwezi kupunguzwa na shirika la utawala), na Kamiti ya Ufuatiliaji ya Nanga inafuatilia shughuli za haki.</p><h2 id="_5-mamlaka-ya-ufuatiliaji-kamiti-ya-ufuatiliaji-ya-nanga" tabindex="-1">5. Mamlaka ya Ufuatiliaji: Kamiti ya Ufuatiliaji ya Nanga <a class="header-anchor" href="#_5-mamlaka-ya-ufuatiliaji-kamiti-ya-ufuatiliaji-ya-nanga" aria-label="Permalink to &quot;5. Mamlaka ya Ufuatiliaji: Kamiti ya Ufuatiliaji ya Nanga&quot;">​</a></h2><p>Kamiti ya Ufuatiliaji ya Nanga ni shirika la ufuatiliaji la uhuru, na linatekeleza mamlaka ya nne - mamlaka ya ufuatiliaji, na inafanya ufuatiliaji wa kamili juu ya mashirika yote ya mamlaka.</p><h3 id="_1-muundo-na-asili-2" tabindex="-1">(1) Muundo na Asili <a class="header-anchor" href="#_1-muundo-na-asili-2" aria-label="Permalink to &quot;(1) Muundo na Asili&quot;">​</a></h3><ul><li><strong>Mfumo wa Uwajibikaji wa Mkurugenzi</strong>: Kamiti ya ufuatiliaji inatekeleza mfumo wa uwajibikaji wa mkurugenzi, na mkurugenzi anachaguliwa na Baraza la Nanga, na muda wake ni miaka mitano, na hawezi kuchaguliwa tena.</li><li><strong>Muundo wa Wanachama</strong>: Wanachama wa kamiti wanajumuisha wawakilishi wa kabila zote, wataalamu wa sheria, na wawakilishi wa umma, na kati yao wanachama wa muda mzima hawachini ya nusu.</li><li><strong>Hakikisho ya Uhuru</strong>: Bajeti ya kamiti ya ufuatiliaji inategemezwa kwa uhuru, na wanachama hawezi kufukuzwa bila sababu ya kisheria, na kuhakikisha uhuru wa ufuatiliaji.</li></ul><h3 id="_2-eneo-la-mamlaka-2" tabindex="-1">(2) Eneo la Mamlaka <a class="header-anchor" href="#_2-eneo-la-mamlaka-2" aria-label="Permalink to &quot;(2) Eneo la Mamlaka&quot;">​</a></h3><ol><li><strong>Ufuatiliaji wa Uaminifu</strong>: Kufuatilia hali ya uaminifu na kujidiscipline yenaweke ya wafanyakazi wote wa umma, kuchunguza na kuadhibu tabia za ufisadi, rushwa, unyanyafu wa mamlaka kwa manufaa ya kibinafsi, n.k.</li><li><strong>Ufuatiliaji wa Ufanisi</strong>: Kufuatilia ufanisi wa kazi ya kila shirika la mamlaka, kuchunguza na kuadhibu tabia za kutotenda, kutenda kwa ubaguzi, kutenda polepole, n.k.</li><li><strong>Ufuatiliaji wa Utekelezaji wa Sheria</strong>: Kufuatilia hali ya utekelezaji wa sheria, kuchunguza na kuadhibu tabia za kutotii sheria, utekelezaji usio mkali wa sheria, kutochunguza tabia za kikatili, n.k.</li><li><strong>Ufuatiliaji wa Fedha</strong>: Kufuatilia hali ya matumizi ya fedha za umma, kuchunguza na kuadhibu tabia za upotevu wa rasilimali za umma, ugeni wa fedha za umma, n.k.</li><li><strong>Ufuatiliaji wa Tabia za Mauaji</strong>: Kufuatilia maalum kurudiwa kwa tabia za mauaji, kuchunguza na kuadhibu tabia za kutumia mamlaka kufanya mauaji.</li></ol><h3 id="_3-njia-za-ufuatiliaji" tabindex="-1">(3) Njia za Ufuatiliaji <a class="header-anchor" href="#_3-njia-za-ufuatiliaji" aria-label="Permalink to &quot;(3) Njia za Ufuatiliaji&quot;">​</a></h3><ul><li>Ufuatiliaji wa kila siku: Kufanya ufuatiliaji wa kila siku kupitia ziara, ukaguzi, ukaguzi wa fedha, n.k.</li><li>Ufuatiliaji maalum: Kufanya ufuatiliaji maalum针对 nyanja fulani au tatizo fulani.</li><li>Kupokea malalamiko: Kupokea malalamiko na malalamiko ya umma kuhusu tabia za kikatili na za kikatili.</li><li>Uchunguzi na uwajibikaji: Kuchunguza tabia zinazoshukiwa za kikatili na za kikatili, na kutoa mapendekezo ya uwajibikaji.</li><li>Kupasha habari kwa umma: Kuchapisha kwa mara kwa mara hali ya ufuatiliaji na kesi za kawaida, na kupokea ufuatiliaji wa kijamii.</li></ul><h2 id="_6-mfumo-wa-usawa-wa-mamlaka" tabindex="-1">6. Mfumo wa Usawa wa Mamlaka <a class="header-anchor" href="#_6-mfumo-wa-usawa-wa-mamlaka" aria-label="Permalink to &quot;6. Mfumo wa Usawa wa Mamlaka&quot;">​</a></h2><p>Uhusiano wa usawa kati ya kila shirika la mamlaka unaonyeshwa katika jedwali lifuatalo:</p><table tabindex="0"><thead><tr><th>Uhusiano wa Usawa</th><th>Njia ya Usawa</th></tr></thead><tbody><tr><td>Mamlaka ya Kisheria inazuia Mamlaka ya Utawala</td><td>Baraza lina mamlaka ya kufukuza mwenyekiti wa utawala, kukataa mapendekezo ya utawala, kukubali bajeti</td></tr><tr><td>Mamlaka ya Kisheria inazuia Mamlaka ya Haki</td><td>Baraza lina mamlaka ya kuteua wanaohukumu, kurekebisha sheria ya shirikisho la mahakama, kuwasilisha mashtaka ya kufukuza wanaohukumu</td></tr><tr><td>Mamlaka ya Utawala inazuia Mamlaka ya Kisheria</td><td>Mwenyekiti wa utawala ana mamlaka ya kukataa sheria iliyopitishwa na baraza (baraza linaweza kurejea kukataa kwa多数 zaidi ya theluthi mbili)</td></tr><tr><td>Mamlaka ya Utawala inazuia Mamlaka ya Haki</td><td>Idara ya utawala inahusika na utekelezaji wa hukumu za mahakama, kusimamia maswala ya utawala wa haki</td></tr><tr><td>Mamlaka ya Haki inazuia Mamlaka ya Kisheria</td><td>Mahakama ina mamlaka ya kufanya uchunguzi wa katiba, kutangaza sheria zisiyo na ufanisi</td></tr><tr><td>Mamlaka ya Haki inazuia Mamlaka ya Utawala</td><td>Mahakama ina mamlaka ya kuhukumu mashtaka ya utawala, kuchunguza halali ya tabia ya utawala</td></tr><tr><td>Mamlaka ya Ufuatiliaji inazuia Mamlaka Tatu</td><td>Kamiti ya ufuatiliaji inafanya ufuatiliaji wa kamili juu ya mamlaka tatu za kisheria, utawala, na haki</td></tr><tr><td>Mamlaka Tatu inazuia Mamlaka ya Ufuatiliaji</td><td>Baraza linateuza mkurugenzi wa kamiti ya ufuatiliaji, na mahakama inahukumu tabia za kikatili za kamiti ya ufuatiliaji</td></tr></tbody></table><h2 id="_7-usimamizi-wa-msingi-na-ujitawala" tabindex="-1">7. Usimamizi wa Msingi na Ujitawala <a class="header-anchor" href="#_7-usimamizi-wa-msingi-na-ujitawala" aria-label="Permalink to &quot;7. Usimamizi wa Msingi na Ujitawala&quot;">​</a></h2><p>Chini ya muundo wa usimamizi wa kati, mfumo wa ujitawala wa msingi unatekelezwa:</p><ul><li><strong>Ujitawala wa Jumuiya/Kijiji</strong>: Jumuiya za msingi na vijiji wanatekeleza ujitawala wa wakazi, na kuchagua shirika la ujitawala kupitia mkutano wa wakazi kusimamia maswala ya umma ya eneo hilo.</li><li><strong>Ujitawala wa Plano</strong>: Kila plano, chini ya masharti ya kutii katiba na sheria, inafurahia ujitawala wa fulani, na inaweza kuandaa kanuni za utekelezaji za undani kulingana na hali ya eneo hilo.</li><li><strong>Ujitawala wa Kabila</strong>: Maeneo ya makazi ya kila kabila yanaweza kuanzisha shirika la ujitawala wa kabila kusimamia maswala ya ndani ya kabila yao mwenyewe, lakini havifai kuvunja katiba na sheria.</li><li><strong>Ujitawala wa Seksheni</strong>: Kila sekta inaweza kuanzisha chama cha sekta kufanya kujidiscipline ya sekta na usimamizi wa sekta.</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Muundo wa usimamizi na usawa wa mamlaka ni hakikisho cha kitaaluma kwa utulivu wa muda mrefu wa ustaarabu wa usawa wa nanga. Kupitia muundo wa &quot;mgawanyiko wa mamlaka tatu, usawa wa mamlaka nne&quot;, mfumo wa uwakilishi wa ushiriki wa kabila zote, na muundo wa usimamizi wa ujitawala wa msingi, inahakikisha mamlaka inafanya kazi chini ya jua la jua, inazuia ukaribishaji wa mamlaka na kurudiwa kwa usimamizi wa mauaji, na inatoa mfumo wa usimamizi ulio thabiti, wa haki, na wenye ufanisi kwa maendeleo ya pamoja ya kabila zote.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Kanuni za Msingi za Katiba ya Usawa)</li><li>48-司法体系与裁决机制 (Mfumo wa Haki na Mfumo wa Maamuzi)</li><li>03-共生文明宪章 (Hati ya Nguvu za Ustaarabu wa Usawa)</li><li>36-社会结构与阶层流动 (Muundo wa Kijamii na Uhamiaji wa Tabaka)</li></ul>',45)])])}const d=i(l,[["render",m]]);export{o as __pageData,d as default};
